export type Sport = 'basketball' | 'football'

export type Followed = { sport: Sport; slug: string; name: string }

export type Choice = Followed & { label: string }

export type LiveGame = {
  key: string
  home: string
  away: string
  homeScore: string
  awayScore: string
  homeLogo: string
  awayLogo: string
  statusText: string
  minute: string
  competition: string
}

export type Reading = {
  game: LiveGame | null
  sport: Followed['sport']
  slug: string
  followedSide: 'home' | 'away' | null
  isStale: boolean
  at: number
}

